Your expense tracker is below. Add what you spent, pick a category, and it keeps the month's total and a split by category. Set a monthly budget to see how much is left.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f6f7f9;color:#1d2330}
  h2{margin:0 0 10px;font-size:18px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font:inherit;padding:7px 9px;border:1px solid #c9ced8;border-radius:6px;background:#fff}
  input{flex:1;min-width:90px}
  button{background:#2f6fed;color:#fff;border:0;cursor:pointer}
  button.x{background:none;color:#b3261e;padding:2px 8px}
  .big{font-size:26px;font-weight:600}
  .muted{color:#667085;font-size:13px}
  .bar{height:10px;border-radius:5px;background:#e6e9ef;overflow:hidden;margin:4px 0 10px}
  .bar i{display:block;height:100%;background:#2f6fed}
  .over{color:#b3261e}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eef0f4}
  .item:last-child{border:0}
</style>
</head>
<body>
<div class="card">
  <h2>Month</h2>
  <div class="row">
    <input type="month" id="month">
    <input type="number" id="budget" placeholder="Monthly budget (₹)">
  </div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
  <div class="bar"><i id="used" style="width:0"></i></div>
</div>

<div class="card">
  <h2>Add an expense</h2>
  <div class="row">
    <input id="what" placeholder="What was it for?">
    <input type="number" id="amt" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input type="date" id="date">
    <button id="add">Add</button>
  </div>
</div>

<div class="card">
  <h2>By category</h2>
  <div id="cats" class="muted">Nothing yet.</div>
</div>

<div class="card">
  <h2>Expenses</h2>
  <div id="list" class="muted">Nothing yet.</div>
</div>

<script>
var $=function(i){return document.getElementById(i)};
var data={items:[],budget:{}};
try{var s=localStorage.getItem('exp1');if(s)data=JSON.parse(s)}catch(e){}
function save(){try{localStorage.setItem('exp1',JSON.stringify(data))}catch(e){}}
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
var today=new Date().toISOString().slice(0,10);
$('date').value=today;
$('month').value=today.slice(0,7);

function render(){
  var m=$('month').value;
  var items=data.items.filter(function(x){return x.date.slice(0,7)===m});
  var total=items.reduce(function(a,x){return a+x.amt},0);
  var b=data.budget[m]||0;
  $('budget').value=b||'';
  $('total').textContent=inr(total)+' spent';
  var left=$('left'),used=$('used');
  if(b){
    var r=b-total;
    left.textContent=r>=0?inr(r)+' left of '+inr(b):inr(-r)+' over the budget of '+inr(b);
    left.className=r>=0?'muted':'muted over';
    used.style.width=Math.min(100,total/b*100)+'%';
    used.style.background=r>=0?'#2f6fed':'#b3261e';
  }else{left.textContent='Set a budget to see what is left.';used.style.width='0'}

  var by={};
  items.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var cats=$('cats');cats.textContent='';
  var keys=Object.keys(by).sort(function(a,c){return by[c]-by[a]});
  if(!keys.length)cats.textContent='Nothing yet.';
  keys.forEach(function(k){
    var d=document.createElement('div');
    var t=document.createElement('div');
    t.textContent=k+': '+inr(by[k])+' ('+Math.round(by[k]/total*100)+'%)';
    var bar=document.createElement('div');bar.className='bar';
    var i=document.createElement('i');i.style.width=(by[k]/total*100)+'%';
    bar.appendChild(i);d.appendChild(t);d.appendChild(bar);cats.appendChild(d);
  });

  var list=$('list');list.textContent='';
  if(!items.length)list.textContent='Nothing yet.';
  items.sort(function(a,c){return c.date.localeCompare(a.date)}).forEach(function(x){
    var row=document.createElement('div');row.className='item';
    var l=document.createElement('div');
    l.textContent=x.what+' · '+x.cat;
    var sm=document.createElement('div');sm.className='muted';sm.textContent=x.date;
    l.appendChild(sm);
    var r=document.createElement('div');
    r.textContent=inr(x.amt)+' ';
    var del=document.createElement('button');del.className='x';del.textContent='Delete';
    del.onclick=function(){data.items=data.items.filter(function(y){return y!==x});save();render()};
    r.appendChild(del);
    row.appendChild(l);row.appendChild(r);list.appendChild(row);
  });
}
$('add').onclick=function(){
  var a=parseFloat($('amt').value);
  if(!(a>0))return;
  data.items.push({what:$('what').value.trim()||'Expense',amt:a,cat:$('cat').value,date:$('date').value||today});
  $('what').value='';$('amt').value='';
  $('month').value=($('date').value||today).slice(0,7);
  save();render();
};
$('budget').onchange=function(){data.budget[$('month').value]=parseFloat($('budget').value)||0;save();render()};
$('month').onchange=render;
render();
</script>
</body>
</html>
```

